import re
from collections import Counter


def tokenize(text):
    """Split text into lowercase words. Apostrophes inside words are kept."""
    return re.findall(r"[a-z]+", text.lower())


def word_count(text):
    return len(tokenize(text))


def top_words(text, n=3):
    """Return the n most common words as (word, count), ties broken alphabetically."""
    counts = Counter(tokenize(text))
    return sorted(counts.items(), key=lambda kv: -kv[1])[:n]

import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from textstats import word_count, top_words


def test_word_count_simple():
    assert word_count("the cat sat") == 3


def test_apostrophes_kept():
    assert word_count("don't stop") == 2


def test_top_words_ties_alphabetical():
    assert top_words("b a b a c", n=2) == [("a", 2), ("b", 2)]


if __name__ == "__main__":
    import sys
    failed = 0
    for name, fn in sorted(globals().items()):
        if name.startswith("test_") and callable(fn):
            try:
                fn()
                print("PASS", name)
            except AssertionError as e:
                failed += 1
                print("FAIL", name, e)
    print(f"{failed} failed")
    sys.exit(1 if failed else 0)

